__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"STARTERS",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"DURATIONS",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"LIMITS",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"RED_FLAGS",{enumerable:!0,get:function(){return s}});const o={'Low back':{why:'Most low backs feel better with gentle movement and a little hip strength, not rest.',moves:[{name:'Cat cow',dose:'2 x 10 slow',how:'On hands and knees, round your back up, then let it gently sag. Stay in a comfortable range.'},{name:'Glute bridge',dose:'2 x 10',how:'Lying on your back, squeeze your glutes and lift your hips. Pause 2 seconds at the top.'},{name:'Walk',dose:'10 to 20 min',how:'Easy pace, most days. Walking is one of the best things for a cranky back.'}]},Neck:{why:'Stiff, sore necks usually respond to gentle motion and upper back strength.',moves:[{name:'Chin tucks',dose:'2 x 10, 3 sec hold',how:'Sit tall and slide your chin straight back, like making a double chin. Relax and repeat.'},{name:'Open book',dose:'2 x 8 each side',how:'Lie on your side, knees bent. Open your top arm across like a book, following it with your eyes.'},{name:'Shoulder blade squeeze',dose:'2 x 12',how:'Squeeze your shoulder blades back and down. Hold 3 seconds.'}]},Shoulder:{why:'Shoulders get better with motion and building up the small muscles that control them.',moves:[{name:'Pendulum swings',dose:'30 sec each direction',how:'Lean on a table and let your arm hang. Make small relaxed circles.'},{name:'Wall slides',dose:'2 x 10',how:'Forearms on a wall, slide them up as far as is comfortable, then back down.'},{name:'Band rows',dose:'2 x 12',how:'Pull a band toward your ribs, squeezing your shoulder blades together.'}]},Hip:{why:'Most hip pain improves with strength around the hip and keeping it moving.',moves:[{name:'Glute bridge',dose:'2 x 10',how:'Lying on your back, squeeze your glutes and lift your hips. Pause at the top.'},{name:'Side lying leg raise',dose:'2 x 10 each side',how:'Lie on your side and lift your top leg slightly behind you, toes pointing forward.'},{name:'Hip flexor stretch',dose:'2 x 30 sec each side',how:'Half kneeling, tuck your hips under and shift forward gently until you feel the front of the hip.'}]},Knee:{why:'Knees love load that builds week by week. Strong quads and hips take pressure off the joint.',moves:[{name:'Quad sets',dose:'2 x 10, 5 sec hold',how:'Sit with your leg straight and press the back of your knee down by tightening your thigh.'},{name:'Sit to stand',dose:'2 x 8',how:'Stand up from a chair without using your hands. Sit back down slowly.'},{name:'Step ups',dose:'2 x 8 each side',how:'Step up onto a low step, driving through your heel. Use a rail if you need it.'}]},'Ankle or foot':{why:'Feet and ankles get better with mobility, calf strength and balance.',moves:[{name:'Ankle circles',dose:'10 each direction',how:'Draw slow circles with your foot, as big as is comfortable.'},{name:'Calf raises',dose:'2 x 12',how:'Rise up onto your toes, pause, and lower slowly. Hold a counter for balance.'},{name:'Single leg balance',dose:'3 x 20 sec each side',how:'Stand on one foot near a counter. Make it harder by turning your head side to side.'}]},'After surgery':{why:'After surgery, the right plan depends on your surgeon\u2019s protocol. Gentle circulation work is a safe start.',moves:[{name:'Ankle pumps',dose:'20 reps every hour awake',how:'Point and flex your feet. Keeps blood moving and reduces stiffness.'},{name:'Deep breathing',dose:'5 slow breaths, 3 times a day',how:'Breathe in through your nose, long exhale through your mouth.'},{name:'Short walks',dose:'As cleared by your surgeon',how:'Short, frequent walks beat one long one early on.'}]},'Sport performance':{why:'Performance starts with how you move. These cover the basics most athletes miss.',moves:[{name:'World\u2019s greatest stretch',dose:'5 each side',how:'Lunge forward, drop your elbow toward your front foot, then rotate and reach up.'},{name:'Single leg RDL',dose:'2 x 8 each side',how:'Hinge forward on one leg with a flat back, reaching your free leg behind you.'},{name:'Dead bug',dose:'2 x 8 each side',how:'On your back, low back gently pressed down. Reach opposite arm and leg away slowly.'}]}},t=['Less than 2 weeks','2 to 6 weeks','6 weeks to 3 months','More than 3 months'],n=['Sleep','Sitting','Work','Lifting','Running','Sports','Playing with kids','Daily chores'],s='Get checked right away if you have numbness in the groin or saddle area, new trouble controlling your bladder or bowels, fever with back pain, unexplained weight loss, or pain after a fall or accident.'},896,[]);